#!/usr/bin/env bash
# check-generated.sh is the drift check of the checked-in generated code:
# the protobuf codecs and the WIT bindings of the examples. A job
# regenerates them with the pinned generator and then runs this script,
# which fails when the working tree differs from what is checked in.
#
# One difference is allowed: the generator's own version, which a
# generated file carries in a stamp. A generator bump whose output is
# otherwise identical therefore passes with the old stamp still checked
# in, and the stamp moves the next time the output changes for real. Any
# other difference fails: a changed, added or removed line (one beside a
# stamp included), a stamp added or removed, a file created, deleted or
# renamed, a changed file mode.
#
# The stamps are listed here and nowhere else. Each is tied to the file
# names its generator writes and to its whole line, and only the version
# in it may differ:
#
#   wit-bindgen (*.c, *.h, *.go, *.mbt), the first line:
#     // Generated by `wit-bindgen` 0.62.0. DO NOT EDIT!
#   wit-bindgen c (*_component_type.o): the `producers` custom section of
#     the component encoded in the object's `component-type:<world>`
#     section, which names wit-bindgen-c and wit-component by version.
#     Every other byte of the object is compared.
#   nanopb (*.pb.c, *.pb.h):
#     /* Generated by nanopb-0.4.9.1 */
#   protoc-gen-es (*_pb.js, *_pb.d.ts), the parameters compared:
#     // @generated by protoc-gen-es v2.17.0 with parameter "..."
#   protoc's Python generator (*_pb2.py), two places stating one version:
#     # Protobuf Python Version: 7.35.1
#     _runtime_version.ValidateProtobufRuntimeVersion(
#         _runtime_version.Domain.PUBLIC,
#         7,
#         35,
#         1,
#         '',
#     The second is a check at import: the protobuf runtime refuses a
#     codec generated by a protoc newer than itself and accepts an older
#     one of its major. A codec left at an older stamp therefore loads,
#     and the python example's tests load the checked-in codec on the
#     runtime its requirements.txt pins, so a stamp the runtime refuses
#     fails there.
#
# The other checked-in generators stamp no version: protoc-gen-zig,
# protoc-gen-mbt and protoc's C# generator.
#
# usage: check-generated.sh [-m <hint>] [<path>...]
#
# The paths (the whole repository when none is given) are read from the
# current directory, as git reads them; the hint is printed on a failure
# and says what to run. hack/check-generated-test.sh is the test.
set -euo pipefail

hint="the generated code is not up to date; regenerate it and commit the result"
while getopts m: opt; do
	case "$opt" in
	m) hint=$OPTARG ;;
	*)
		echo "usage: $0 [-m <hint>] [<path>...]" >&2
		exit 2
		;;
	esac
done
shift $((OPTIND - 1))
if [ $# -eq 0 ]; then
	set -- ':/'
fi

# normalise prints the file on stdin with every version stamp its name
# allows replaced by a fixed word, so two files that differ in a stamp's
# version alone print the same bytes. Each text rule replaces its first
# match only.
# shellcheck disable=SC2016
normalise='
use strict;
use warnings;

my $name = shift;
binmode STDIN;
binmode STDOUT;
local $/;
my $data = <STDIN>;
$data = "" unless defined $data;
my $version = qr/[0-9][0-9A-Za-z.+-]*/;

sub leb {
	my ($bytes, $pos) = @_;
	my ($value, $shift) = (0, 0);
	while (1) {
		die "truncated\n" if $$pos >= length $$bytes;
		my $byte = ord substr($$bytes, $$pos++, 1);
		$value |= ($byte & 0x7f) << $shift;
		return $value unless $byte & 0x80;
		$shift += 7;
		die "oversized\n" if $shift > 35;
	}
}

# The sections of a module or a component: [id, payload] each.
sub sections {
	my ($binary) = @_;
	die "not WebAssembly\n" unless length($binary) >= 8 && substr($binary, 0, 4) eq "\0asm";
	my $pos = 8;
	my @sections;
	while ($pos < length $binary) {
		my $id = ord substr($binary, $pos++, 1);
		my $size = leb(\$binary, \$pos);
		die "truncated\n" if $pos + $size > length $binary;
		push @sections, [$id, substr($binary, $pos, $size)];
		$pos += $size;
	}
	return (substr($binary, 0, 8), @sections);
}

# The name and the data of a custom section.
sub custom {
	my ($payload) = @_;
	my $pos = 0;
	my $size = leb(\$payload, \$pos);
	die "truncated\n" if $pos + $size > length $payload;
	return (substr($payload, $pos, $size), substr($payload, $pos + $size));
}

sub record {
	my ($id, $payload) = @_;
	return pack("C N/a*", $id, $payload);
}

# The object with its sections length-prefixed again and, in the component
# a component-type section encodes, the producers section left out.
sub object {
	my ($header, @sections) = sections($_[0]);
	my $out = $header;
	for my $section (@sections) {
		my ($id, $payload) = @$section;
		if ($id == 0) {
			my ($section_name, $encoded) = custom($payload);
			if ($section_name =~ /\Acomponent-type:/) {
				my ($inner_header, @inner) = sections($encoded);
				my $component = $inner_header;
				for my $inner_section (@inner) {
					my ($inner_id, $inner_payload) = @$inner_section;
					next if $inner_id == 0 && (custom($inner_payload))[0] eq "producers";
					$component .= record($inner_id, $inner_payload);
				}
				$payload = pack("N/a*", $section_name) . $component;
			}
		}
		$out .= record($id, $payload);
	}
	return $out;
}

if ($name =~ /_component_type\.o\z/) {
	$data = object($data);
} elsif ($name =~ /\.pb\.[ch]\z/) {
	$data =~ s{^/\* Generated by nanopb-$version \*/$}{/* Generated by nanopb-VERSION */}m;
} elsif ($name =~ /_pb\.(?:js|d\.ts)\z/) {
	$data =~ s{^// \@generated by protoc-gen-es v$version with parameter }{// \@generated by protoc-gen-es vVERSION with parameter }m;
} elsif ($name =~ /_pb2\.py\z/) {
	$data =~ s{^# Protobuf Python Version: $version$}{# Protobuf Python Version: VERSION}m;
	$data =~ s{^(_runtime_version\.ValidateProtobufRuntimeVersion\(\n    _runtime_version\.Domain\.PUBLIC,\n)    [0-9]+,\n    [0-9]+,\n    [0-9]+,\n    \x27[0-9A-Za-z.+-]*\x27,\n}{$1    VERSION,\n}m;
} elsif ($name =~ /\.(?:c|h|go|mbt)\z/) {
	$data =~ s{\A// Generated by `wit-bindgen` $version\. DO NOT EDIT!\n}{// Generated by `wit-bindgen` VERSION. DO NOT EDIT!\n};
}
print $data;
'

top=$(git rev-parse --show-toplevel)
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT

drifted=()
stamped=()

# One entry of git status: the two status letters and the path, from the
# top of the repository.
judge() {
	local status=$1 path=$2
	if [ "$status" != " M" ] || [ ! -f "$top/$path" ] || [ -L "$top/$path" ]; then
		drifted+=("$status $path")
		return
	fi
	git cat-file blob ":$path" >"$work/checked-in"
	if cmp -s "$work/checked-in" "$top/$path"; then
		drifted+=("$status $path (the file mode)")
		return
	fi
	if perl -e "$normalise" "$path" <"$work/checked-in" >"$work/before" 2>/dev/null &&
		perl -e "$normalise" "$path" <"$top/$path" >"$work/after" 2>/dev/null &&
		cmp -s "$work/before" "$work/after"; then
		stamped+=("$path")
		return
	fi
	drifted+=("$status $path")
}

while IFS= read -r -d '' entry; do
	status=${entry:0:2}
	path=${entry:3}
	case "$status" in
	R* | C* | ?R | ?C)
		# A rename or a copy carries the path it came from as a second entry.
		IFS= read -r -d '' _ || true
		;;
	esac
	judge "$status" "$path"
done < <(git status --porcelain=v1 -z --untracked-files=all -- "$@")

if [ ${#drifted[@]} -gt 0 ]; then
	echo "$hint:"
	printf '%s\n' "${drifted[@]}"
	if [ ${#stamped[@]} -gt 0 ]; then
		echo "the generator's version alone differs, which is no drift, in:"
		printf '   %s\n' "${stamped[@]}"
	fi
	git --no-pager diff -- "$@"
	exit 1
fi
if [ ${#stamped[@]} -gt 0 ]; then
	echo "the generator's version alone differs from what is checked in, which is no drift, in:"
	printf '   %s\n' "${stamped[@]}"
fi
